import numpy as np

# MECHANISM: Use a quadratic decay function with a bias to prioritize bins based on remaining capacity.

def priority(item, bins):
    bias = 150 - item
    return np.array([bias / (b - item + 1) for b in bins])

import numpy as np
# MECHANISM: Use a Gaussian decay function to prioritize bins based on remaining capacity.

def priority(item, bins):
    def s(b, item):
        g = b - item
        if g <= 10: return 1.0
        return np.exp(-(g - 10) ** 2 / (2 * 10 ** 2))
    return np.array([s(b, item) for b in bins])

